// Builds every generated file from its editable source:
//   src/page.html + assets/data/*.json             -> route pages for KR (/), EN (/en/) and JP (/ja/)
//   src/app/template.html, src/app/component.js    -> assets/app/app.js (shared by every route page)
//   assets/data/*-content.json                     -> assets/data/*-content.js
//   assets/data/works-data.json, site-content.json -> works/<slug>/, news/<slug>/ detail pages per language
//   assets/data/seo-content.json + the above       -> sitemap.xml
//
//   node scripts/build.mjs          rewrite generated files
//   node scripts/build.mjs --check  fail if any generated file is out of date
//
// Pages load the app from assets/app/app.js and the data as window globals
// from the .js files. Edit the sources, never the generated output.
import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { nanumCharacters, PREVIEW_SOURCES } from './font-coverage.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');
const read = (file) => readFile(path.join(root, file), 'utf8');
const readJson = async (file) => JSON.parse(await read(file));

// Content keys stay kr/en/jp; URLs and html lang use ISO codes.
const languages = [
  { key: 'kr', html: 'ko', prefix: '', locale: 'ko_KR', label: '한국어' },
  { key: 'en', html: 'en', prefix: '/en', locale: 'en_US', label: 'English' },
  { key: 'jp', html: 'ja', prefix: '/ja', locale: 'ja_JP', label: '日本語' },
];

const labels = {
  kr: { nav: '주요 페이지', languages: '언어', storyTypes: '어떤 이야기와 일하는가', trackRecord: 'Track Record', latestNews: '최신 소식', members: '멤버', works: '작업물', news: '소식', contact: '프로젝트 문의' },
  en: { nav: 'Main pages', languages: 'Language', storyTypes: 'Stories we work with', trackRecord: 'Track Record', latestNews: 'Latest News', members: 'Members', works: 'Works', news: 'News', contact: 'Project Inquiry' },
  jp: { nav: '主要ページ', languages: '言語', storyTypes: '私たちが向き合う物語', trackRecord: 'Track Record', latestNews: '最新ニュース', members: 'メンバー', works: '制作実績', news: 'ニュース', contact: 'プロジェクトのご相談' },
};

const [shell, template, component, siteJsonText, seoJsonText, works] = await Promise.all([
  read('src/page.html'),
  readFile(path.join(root, 'src/app/template.html')),
  readFile(path.join(root, 'src/app/component.js')),
  read('assets/data/site-content.json'),
  read('assets/data/seo-content.json'),
  readJson('assets/data/works-data.json'),
]);
const site = JSON.parse(siteJsonText);
const seo = JSON.parse(seoJsonText);
const baseUrl = seo.baseUrl.replace(/\/+$/, '');

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const paragraphs = (value) => String(value ?? '').trim().split(/\n{2,}/).filter(Boolean)
  .map((block) => `<p>${block.split('\n').map(esc).join('<br>')}</p>`).join('\n');
const localized = (item, lang) => ({ ...item, ...((item && item.translations && item.translations[lang]) || {}) });
const urlFor = (lang, pagePath) => `${baseUrl}${lang.prefix}${pagePath}`;
const fileFor = (lang, pagePath) => `${lang.prefix.slice(1)}${pagePath}index.html`.replace(/^\//, '');
// Nanum Gothic via Google Fonts `text=`: one small file per weight holding only the characters the site uses.
const nanumUrl = (chars) => `https://fonts.googleapis.com/css2?family=Nanum+Gothic:wght@400;700&amp;display=swap&amp;text=${encodeURIComponent(chars)}`;
const nanumFontUrl = nanumUrl(await nanumCharacters(root));

// Cloudflare Web Analytics: set seo-content.json → analytics.cloudflareToken to switch it on.
const analyticsToken = String(seo.analytics?.cloudflareToken || '').trim();
const analyticsTag = analyticsToken
  ? `<script defer src="https://static.cloudflareinsights.com/beacon.min.js" data-cf-beacon='${JSON.stringify({ token: analyticsToken })}'></script>`
  : '';
const version = (text) => createHash('sha256').update(text).digest('hex').slice(0, 12);

// The dc-runtime in support.js boots on DOMContentLoaded from two base64 <script> blocks.
// Instead of repeating ~360 KB of them in every page, one cached script inserts them in place.
const makeAppBundle = (template, component) => `// GENERATED by scripts/build.mjs from src/app/ — do not edit.
(function (app) {
  var here = document.currentScript;
  function base64(text) {
    var bytes = new TextEncoder().encode(text), binary = '';
    for (var i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
    return btoa(binary);
  }
  function insert(attributes, text) {
    var el = document.createElement('script');
    el.type = 'application/octet-stream';
    for (var name in attributes) el.setAttribute(name, attributes[name]);
    el.textContent = base64(text);
    here.parentNode.insertBefore(el, here);
  }
  insert({ 'data-dc-template-b64': '' }, app.template);
  insert({ 'data-dc-script': '', 'data-dc-script-b64': '', 'data-props': app.props }, app.script);
})(${JSON.stringify({ template: template.toString('utf8'), script: component.toString('utf8'), props: '{"$preview":{"width":"100%","height":"100vh"}}' })});
`;
const appBundle = makeAppBundle(template, component);

const dataScript = (data, name, aliases = []) =>
  [`window.${name} = ${JSON.stringify(data, null, 2)};`, ...aliases.map((alias) => `window.${alias} = window.${name};`)].join('\n') + '\n';
const siteScript = dataScript(site, 'TALETONE_CONTENT');
const seoScript = dataScript(seo, 'TALETONE_SEO_CONTENT', ['TALETONE_SEO']);

function pageCopy(page, lang) {
  return { title: page.title, description: page.description, ...((page.translations && page.translations[lang.key]) || {}) };
}

function jsonLd(page, lang) {
  const copy = pageCopy(page, lang);
  const home = pageCopy(seo.pages.find((p) => p.key === 'home'), lang);
  const rootUrl = `${baseUrl}/`;
  const organization = {
    '@type': 'Organization',
    '@id': `${rootUrl}#organization`,
    name: seo.siteName,
    alternateName: seo.alternateNames,
    url: rootUrl,
    logo: `${rootUrl}assets/icons/icon-512.png`,
    email: 'contact@taletone.net',
    description: home.description,
  };
  const website = {
    '@type': 'WebSite',
    '@id': `${rootUrl}#website`,
    name: seo.siteName,
    alternateName: seo.alternateNames,
    url: rootUrl,
    inLanguage: ['ko', 'en', 'ja'],
    publisher: { '@id': `${rootUrl}#organization` },
  };
  const webPage = {
    '@type': 'WebPage',
    '@id': `${urlFor(lang, page.path)}#webpage`,
    name: copy.title,
    url: urlFor(lang, page.path),
    description: copy.description,
    inLanguage: lang.html,
    isPartOf: { '@id': `${rootUrl}#website` },
    about: { '@id': `${rootUrl}#organization` },
  };
  return JSON.stringify({ '@context': 'https://schema.org', '@graph': [organization, website, webPage] }).replace(/</g, '\\u003c');
}

function noscriptBody(page, lang) {
  const t = labels[lang.key];
  const copy = pageCopy(page, lang);
  const home = localized(site.home, lang.key);
  const sections = [];
  const section = (heading, body) => sections.push(`<section>\n<h2>${esc(heading)}</h2>\n${body}\n</section>`);

  if (page.key === 'home') {
    const projects = localized(site.projects, lang.key);
    section(t.storyTypes, `<p>${esc(projects.subtitle)}</p>\n<p>${esc(projects.description)}</p>`);
    section(t.trackRecord, `<ul>\n${site.trackRecord.map((item) => localized(item, lang.key))
      .map((item) => `<li>${esc(item.value)} · ${esc(item.label)} (${esc(item.note)})</li>`).join('\n')}\n</ul>`);
    section(t.latestNews, `<ul>\n${site.news.map((item) => localized(item, lang.key))
      .map((item) => `<li>${esc(item.date)} · <a href="${newsPath(lang, item)}">${esc(item.title)}</a></li>`).join('\n')}\n</ul>`);
  }
  if (page.key === 'projects') {
    const projects = localized(site.projects, lang.key);
    section(t.storyTypes, `<p>${esc(projects.subtitle)}</p>\n<p>${esc(projects.description)}</p>`);
    for (const card of projects.cards.map((item) => localized(item, lang.key))) {
      sections.push(`<article>\n<h3>${esc(card.label)} · ${esc(card.title)}</h3>\n<p>${esc(card.description)}</p>\n</article>`);
    }
  }
  if (page.key === 'members') {
    for (const member of site.members.map((item) => localized(item, lang.key))) {
      sections.push(`<article>\n<h2>${esc(member.name)} — ${esc(member.role)}</h2>\n${member.tagline ? `<p>${esc(member.tagline)}</p>\n` : ''}${paragraphs(member.creditsText)}\n</article>`);
    }
  }
  if (page.key === 'works') {
    section(t.works, `<ul>\n${worksByDate
      .map((item) => localized(item, lang.key))
      .map((item) => `<li><strong><a href="${workPath(lang, item)}">${esc(item.title)}</a></strong> — ${esc(item.artist)} · ${esc(item.type)} (${esc(item.date)})${item.description ? `<br>${esc(String(item.description).trim())}` : ''}</li>`)
      .join('\n')}\n</ul>`);
  }
  if (page.key === 'news') {
    for (const item of site.news.map((news) => localized(news, lang.key))) {
      sections.push(`<article>\n<h2>${esc(item.date)} · <a href="${newsPath(lang, item)}">${esc(item.title)}</a></h2>\n${paragraphs(item.body || item.summary)}\n</article>`);
    }
  }
  if (page.key === 'contact') {
    const contact = localized(site.contact, lang.key);
    section(`${contact.titleLine1} ${contact.titleAccent}`, `<p>${esc(contact.subtitle)}</p>\n<p>${esc(contact.caption)}</p>`);
  }

  const nav = seo.pages.map((p) => `<a href="${lang.prefix}${p.path}">${esc(p.label)}</a>`).join('\n');
  const switcher = languages.map((l) => `<a href="${l.prefix}${page.path}" hreflang="${l.html}" lang="${l.html}">${esc(l.label)}</a>`).join('\n');
  return `<main class="tt-noscript">
<style>.tt-noscript{font-family:'Nanum Gothic',system-ui,sans-serif;max-width:860px;padding:48px 22px;line-height:1.7;color:#141C30;background:#eef6f4}.tt-noscript a{color:#0E6E7D;font-weight:800;margin-right:10px}</style>
<h1>${esc(copy.title)}</h1>
<p><strong>${esc(home.tagline)}</strong></p>
<p>${esc(copy.description)}</p>
${sections.join('\n')}
<nav aria-label="${esc(t.nav)}">
${nav}
</nav>
<nav aria-label="${esc(t.languages)}">
${switcher}
</nav>
<p><a href="${esc(inquiryMailto(lang))}">${esc(site.contact.email)}</a></p>
</main>`;
}

function renderPage(page, lang, overrides = {}) {
  const copy = pageCopy(page, lang);
  const hreflang = [
    ...languages.map((l) => `<link rel="alternate" hreflang="${l.html}" href="${urlFor(l, page.path)}">`),
    `<link rel="alternate" hreflang="x-default" href="${urlFor(languages[0], page.path)}">`,
  ].join('\n');
  const ogLocale = [
    `<meta property="og:locale" content="${lang.locale}">`,
    ...languages.filter((l) => l !== lang).map((l) => `<meta property="og:locale:alternate" content="${l.locale}">`),
  ].join('\n');
  const values = {
    HTML_LANG: lang.html,
    TITLE: esc(copy.title),
    DESCRIPTION: esc(copy.description),
    URL: urlFor(lang, page.path),
    HREFLANG: hreflang,
    OG_LOCALE: ogLocale,
    SEO_VERSION: version(seoScript),
    SITE_VERSION: version(siteScript),
    JSON_LD: jsonLd(page, lang),
    NOSCRIPT: noscriptBody(page, lang),
    APP_VERSION: version(appBundle),
    ANALYTICS: analyticsTag,
    NANUM_FONT_URL: nanumFontUrl,
    ...overrides,
  };
  return shell.replace(/%%([A-Z_]+)%%/g, (match, key) => {
    if (!(key in values)) throw new Error(`src/page.html: unknown placeholder ${match}`);
    return values[key];
  });
}

// ---- Works / News detail pages: lightweight static pages, one per item and language ----

const detailLabels = {
  kr: { home: '홈', works: 'Works', news: 'News', skip: '본문으로 바로가기', release: '발매일', format: '형태', type: '구분', artist: '아티스트', listen: '미리 듣기', youtube: 'YouTube에서 보기', credits: 'Credits', tracks: '수록곡', versions: '언어별 버전', prev: '이전', next: '다음', allWorks: '전체 작업물 보기', allNews: '전체 소식 보기', viewOnSite: '사이트에서 보기' },
  en: { home: 'Home', works: 'Works', news: 'News', skip: 'Skip to content', release: 'Released', format: 'Format', type: 'Release', artist: 'Artist', listen: 'Preview', youtube: 'Watch on YouTube', credits: 'Credits', tracks: 'Tracklist', versions: 'Language versions', prev: 'Previous', next: 'Next', allWorks: 'All works', allNews: 'All news', viewOnSite: 'View on site' },
  jp: { home: 'ホーム', works: 'Works', news: 'News', skip: '本文へスキップ', release: 'リリース', format: '形態', type: '区分', artist: 'アーティスト', listen: '試聴', youtube: 'YouTubeで見る', credits: 'Credits', tracks: '収録曲', versions: '言語別バージョン', prev: '前へ', next: '次へ', allWorks: 'すべての制作実績', allNews: 'すべてのニュース', viewOnSite: 'サイトで見る' },
};

const worksByDate = [...works.works].sort((a, b) => String(b.date).localeCompare(String(a.date)));
const assetPath = (value) => `/${String(value || '').replace(/\\/g, '/').replace(/^\/+/, '')}`;
const isoDate = (value) => String(value || '').replace(/\./g, '-');
const workPath = (lang, work) => `${lang.prefix}/works/${work.slug}/`;
const newsPath = (lang, item) => `${lang.prefix}/news/${item.slug}/`;
const detailCss = await read('assets/css/detail.css');
const missingSlug = [...works.works, ...site.news].find((item) => !/^[a-z0-9-]+$/.test(item.slug || ''));
if (missingSlug) throw new Error(`Every work and news item needs a lowercase "slug": ${missingSlug.id || missingSlug.slotId}`);

function detailPage({ lang, pathFor, title, description, ogType, image, schema, crumbs, body, preview = false }) {
  const d = detailLabels[lang.key];
  const url = `${baseUrl}${pathFor(lang)}`;
  const fullTitle = `${title} | TALETONE MUSIC`;
  const ld = JSON.stringify({ '@context': 'https://schema.org', '@graph': [
    schema,
    { '@type': 'BreadcrumbList', itemListElement: crumbs.map(([name, href], i) => ({ '@type': 'ListItem', position: i + 1, name, item: `${baseUrl}${href}` })) },
  ] }).replace(/</g, '\\u003c');
  return `<!DOCTYPE html>
<html lang="${lang.html}">
<head>
<meta charset="utf-8">
<title>${esc(fullTitle)}</title>
<meta name="description" content="${esc(description)}">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="referrer" content="strict-origin-when-cross-origin">
<meta name="color-scheme" content="light only">
<meta name="theme-color" content="${preview ? '#0e6e7d' : '#eef6f4'}">
<meta name="robots" content="${preview ? 'noindex, nofollow' : 'index, follow'}">
<link rel="canonical" href="${url}">
${languages.map((l) => `<link rel="alternate" hreflang="${l.html}" href="${baseUrl}${pathFor(l)}">`).join('\n')}
<link rel="alternate" hreflang="x-default" href="${baseUrl}${pathFor(languages[0])}">
<meta property="og:type" content="${ogType}">
<meta property="og:site_name" content="TALETONE MUSIC">
<meta property="og:title" content="${esc(fullTitle)}">
<meta property="og:description" content="${esc(description)}">
<meta property="og:url" content="${url}">
<meta property="og:image" content="${baseUrl}${image}">
<meta property="og:image:alt" content="${esc(title)}">
<meta property="og:locale" content="${lang.locale}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${esc(fullTitle)}">
<meta name="twitter:description" content="${esc(description)}">
<meta name="twitter:image" content="${baseUrl}${image}">
<link rel="icon" href="/assets/icons/favicon-32.png" sizes="32x32" type="image/png">
<link rel="apple-touch-icon" href="/assets/icons/apple-touch-icon.png">
<link rel="manifest" href="/site.webmanifest">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="${nanumFontUrl}" rel="stylesheet">${lang.key === 'jp' ? '\n<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+JP:wght@400..800&amp;display=swap" rel="stylesheet">' : ''}
<link rel="stylesheet" href="${preview ? `/preview/assets/css/detail.css?v=${version(previewDetailCss)}` : `/assets/css/detail.css?v=${version(detailCss)}`}">
<script type="application/ld+json">${ld}</script>
</head>
<body>
<a class="tt-d-skip" href="#main">${esc(d.skip)}</a>
<header class="tt-d-top">
${preview
  ? `<a class="tt-d-brand" href="${lang.prefix}/"><img src="/assets/logo/mark-paper.png" alt="" width="34" height="40"><span class="tt-d-word">TALETONE<small>MUSIC</small></span></a>`
  : `<a class="tt-d-brand" href="${lang.prefix}/"><img src="/assets/logo/mark-ink.png" alt="" width="34" height="40"><span>TALETONE<br>MUSIC</span></a>`}
<nav class="tt-d-langs" aria-label="${esc(labels[lang.key].languages)}">
${languages.map((l) => `<a href="${preview ? '/preview' : ''}${pathFor(l)}" hreflang="${l.html}" lang="${l.html}"${l === lang ? ' aria-current="true"' : ''}>${l.key.toUpperCase()}</a>`).join('\n')}
</nav>
</header>
<main id="main">
<ol class="tt-d-crumbs">
${crumbs.map(([name, href], i) => `<li>${i < crumbs.length - 1 ? `<a href="${href}">${esc(name)}</a>` : `<span aria-current="page">${esc(name)}</span>`}</li>`).join('\n')}
</ol>
${body}
${contactCta(lang)}
</main>
<footer class="tt-d-foot">${esc(localized(site.footerMeta, lang.key).copyright)}</footer>
${preview ? youtubeScript : analyticsTag}
</body>
</html>
`;
}

// Inquiry mail prefilled with the visitor's language template.
function inquiryMailto(lang) {
  const contact = localized(site.contact, lang.key);
  return `mailto:${site.contact.email}?subject=${encodeURIComponent(contact.mailSubject)}&body=${encodeURIComponent(contact.mailTemplate)}`;
}

function contactCta(lang) {
  const contact = localized(site.contact, lang.key);
  return `<section class="tt-d-cta">
<h2>${esc(contact.titleLine1)} ${esc(contact.titleAccent)}</h2>
<p>${esc(contact.subtitle)} ${esc(contact.caption)}</p>
<a class="tt-d-button" href="${esc(inquiryMailto(lang))}">${esc(contact.buttonLabel)} <span aria-hidden="true">&#8594;</span></a>
<p class="tt-d-guide-title">${esc(contact.guideTitle)}</p>
<ul class="tt-d-guide">${contact.guideItems.map((item) => `<li>${esc(item)}</li>`).join('')}</ul>
</section>`;
}

function pager(lang, prev, next, pathOf, titleOf) {
  const d = detailLabels[lang.key];
  if (!prev && !next) return '';
  return `<nav class="tt-d-pager" aria-label="${esc(d.prev)} / ${esc(d.next)}">
${prev ? `<a class="prev" href="${pathOf(lang, prev)}"><small>&#8592; ${esc(d.prev)}</small><strong>${esc(titleOf(prev))}</strong></a>` : ''}
${next ? `<a class="next" href="${pathOf(lang, next)}"><small>${esc(d.next)} &#8594;</small><strong>${esc(titleOf(next))}</strong></a>` : ''}
</nav>`;
}

const listenBlock = (label, audio) => audio
  ? `<p class="tt-d-listen"><span>${esc(label)}</span><audio controls preload="none" src="${esc(assetPath(audio))}"></audio></p>` : '';

function workPage(work, index, lang) {
  const d = detailLabels[lang.key];
  const w = localized(work, lang.key);
  const titleOf = (item) => localized(item, lang.key).title;
  const isAlbum = Array.isArray(work.tracks) && work.tracks.length > 0;
  const facts = [[d.artist, w.artist], [d.release, work.date], [d.format, work.format], [d.type, w.type]].filter(([, v]) => v);
  const tracks = isAlbum ? `<section class="tt-d-section"><h2>${esc(d.tracks)}</h2><div class="tt-d-card"><ol class="tt-d-tracks">
${work.tracks.map((track, i) => {
    const t = localized(track, lang.key);
    return `<li><span class="no">${String(track.trackNo || i + 1).padStart(2, '0')}</span><span class="title">${esc(t.title)}${t.description ? `<small>${esc(String(t.description).trim())}</small>` : ''}</span>${track.audio ? `<audio controls preload="none" src="${esc(assetPath(track.audio))}" aria-label="${esc(d.listen)}: ${esc(t.title)}"></audio>` : ''}</li>`;
  }).join('\n')}
</ol></div></section>` : '';
  const versions = Array.isArray(work.versions) && work.versions.length ? `<section class="tt-d-section"><h2>${esc(d.versions)}</h2><div class="tt-d-card"><ol class="tt-d-tracks">
${work.versions.map((v) => `<li><span class="no">${esc(v.language || '')}</span><span class="title">${esc(localized(v, lang.key).title)}${v.youtube ? ` <small><a href="${esc(v.youtube)}" rel="noopener">${esc(d.youtube)} &#8599;</a></small>` : ''}</span>${v.audio ? `<audio controls preload="none" src="${esc(assetPath(v.audio))}" aria-label="${esc(d.listen)}: ${esc(v.language || '')}"></audio>` : ''}</li>`).join('\n')}
</ol></div></section>` : '';
  const credits = isAlbum ? work.tracks.map((t) => t.credits).filter(Boolean).join('\n\n') || work.credits : work.credits;
  const description = String(w.description || '').trim() || `${w.title} — ${w.artist}`;
  const body = `<article>
<div class="tt-d-hero">
<figure class="tt-d-cover"><img src="${esc(assetPath(work.image))}" alt="${esc(w.title)}" width="1024" height="1024"></figure>
<div>
<p class="tt-d-kicker">${esc(work.format || '')} · ${esc(work.date)}</p>
<h1>${esc(w.title)}</h1>
<p class="tt-d-artist">${esc(w.artist)}</p>
${description ? `<p class="tt-d-lead">${esc(description)}</p>` : ''}
<dl class="tt-d-facts">
${facts.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('\n')}
</dl>
<div class="tt-d-actions">
${work.youtube ? `<a class="tt-d-button" href="${esc(work.youtube)}" rel="noopener">${esc(d.youtube)} <span aria-hidden="true">&#8599;</span></a>` : ''}
<a class="tt-d-button is-ghost" href="${lang.prefix}/works/">${esc(d.allWorks)}</a>
</div>
${isAlbum ? '' : listenBlock(d.listen, work.audio)}
</div>
</div>
${tracks}
${versions}
${credits ? `<section class="tt-d-section"><h2>${esc(d.credits)}</h2><div class="tt-d-card"><pre class="tt-d-credits">${esc(String(credits).trim())}</pre></div></section>` : ''}
</article>
${pager(lang, worksByDate[index - 1], worksByDate[index + 1], workPath, titleOf)}`;
  const schema = {
    '@type': isAlbum ? 'MusicAlbum' : 'MusicRecording',
    '@id': `${baseUrl}${workPath(lang, work)}#work`,
    name: w.title,
    url: `${baseUrl}${workPath(lang, work)}`,
    description,
    image: `${baseUrl}${assetPath(work.image)}`,
    datePublished: isoDate(work.date),
    inLanguage: lang.html,
    byArtist: { '@type': 'MusicGroup', name: w.artist },
    producer: { '@id': `${baseUrl}/#organization` },
    ...(work.youtube ? { sameAs: [work.youtube] } : {}),
    ...(isAlbum ? { numTracks: work.tracks.length, track: work.tracks.map((t) => ({ '@type': 'MusicRecording', name: localized(t, lang.key).title })) } : {}),
  };
  return detailPage({
    lang,
    pathFor: (l) => workPath(l, work),
    title: `${w.title} — ${w.artist}`,
    description: description.length > 160 ? `${description.slice(0, 157)}…` : description,
    ogType: isAlbum ? 'music.album' : 'music.song',
    image: assetPath(work.image),
    schema,
    crumbs: [[d.home, `${lang.prefix}/`], [d.works, `${lang.prefix}/works/`], [w.title, workPath(lang, work)]],
    body,
  });
}

// YouTube id from any watch / share / shorts / embed URL
const youtubeId = (url) => (String(url || '').match(/(?:v=|youtu\.be\/|shorts\/|embed\/)([\w-]{11})/) || [])[1] || '';
// A light YouTube embed: the video's own thumbnail and a play button; the player loads on click.
const liteYouTube = (id, title, label) => `<div class="tt-yt" data-yt="${id}"><img src="https://i.ytimg.com/vi/${id}/maxresdefault.jpg" alt="" width="1280" height="720" onload="if(this.naturalWidth<200)this.src='https://i.ytimg.com/vi/${id}/hqdefault.jpg'"><button type="button" class="tt-yt-play" aria-label="${esc(title)} — ${esc(label)}"><span aria-hidden="true"></span></button></div>`;
const youtubeScript = `<script>document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('.tt-yt-play');if(!b)return;var w=b.closest('.tt-yt'),f=document.createElement('iframe');f.src='https://www.youtube-nocookie.com/embed/'+w.getAttribute('data-yt')+'?autoplay=1&rel=0&playsinline=1';f.title=b.getAttribute('aria-label');f.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture';f.allowFullscreen=true;w.replaceChildren(f);w.classList.add('is-playing');document.querySelectorAll('audio').forEach(function(a){a.pause();});});</script>`;
const watchLabel = { kr: '영상 재생', en: 'Play video', jp: '動画を再生' };

function workPageV2(work, index, lang, list) {
  const d = detailLabels[lang.key];
  const w = localized(work, lang.key);
  const titleOf = (item) => localized(item, lang.key).title;
  const isAlbum = Array.isArray(work.tracks) && work.tracks.length > 0;
  const facts = [[d.release, work.date], [d.format, work.format], [d.type, w.type]].filter(([, v]) => v);
  const id = youtubeId(work.youtube);
  const previewPath = (l, item) => `/preview${workPath(l, item)}`;
  const trackList = (items, numberOf, titleFor, extra) => `<ol class="tt-d-tracks">
${items.map((item, i) => `<li><span class="no">${esc(numberOf(item, i))}</span><span class="title">${esc(titleFor(item))}${extra(item)}</span>${item.audio ? `<audio controls preload="none" src="${esc(assetPath(item.audio))}" aria-label="${esc(d.listen)}: ${esc(titleFor(item))}"></audio>` : ''}</li>`).join('\n')}
</ol>`;
  const tracks = isAlbum ? `<section class="tt-d-section"><h2>${esc(d.tracks)}</h2><div class="tt-d-card">${trackList(work.tracks, (t, i) => String(t.trackNo || i + 1).padStart(2, '0'), (t) => localized(t, lang.key).title, (t) => { const desc = localized(t, lang.key).description; return desc ? `<small>${esc(String(desc).trim())}</small>` : ''; })}</div></section>` : '';
  const versions = Array.isArray(work.versions) && work.versions.length ? `<section class="tt-d-section"><h2>${esc(d.versions)}</h2><div class="tt-d-card">${trackList(work.versions, (v) => v.language || '', (v) => localized(v, lang.key).title, (v) => v.youtube ? ` <small><a href="${esc(v.youtube)}" rel="noopener">${esc(d.youtube)} &#8599;</a></small>` : '')}</div></section>` : '';
  const credits = isAlbum ? work.tracks.map((t) => t.credits).filter(Boolean).join('\n\n') || work.credits : work.credits;
  const description = String(w.description || '').trim() || `${w.title} — ${w.artist}`;
  const body = `<article class="tt-d-work">
<div class="tt-d-stage">${id ? liteYouTube(id, w.title, watchLabel[lang.key]) : `<figure class="tt-d-cover"><img src="${esc(assetPath(work.image))}" alt="${esc(w.title)}" width="1024" height="1024"></figure>`}</div>
<div class="tt-d-body">
<div class="tt-d-main">
<p class="tt-d-kicker">${esc(work.format || '')} · ${esc(work.date)}</p>
<h1>${esc(w.title)}</h1>
<p class="tt-d-artist">${esc(w.artist)}</p>
${description ? `<p class="tt-d-lead">${esc(description)}</p>` : ''}
<div class="tt-d-actions">
${work.youtube ? `<a class="tt-d-button" href="${esc(work.youtube)}" rel="noopener">${esc(d.youtube)} <span aria-hidden="true">&#8599;</span></a>` : ''}
<a class="tt-d-button is-ghost" href="${lang.prefix}/works/">${esc(d.allWorks)}</a>
</div>
</div>
<aside class="tt-d-record">
<img class="tt-d-record-cover" src="${esc(assetPath(work.image))}" alt="${esc(w.title)}" width="1024" height="1024">
<dl class="tt-d-facts">
${facts.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('\n')}
</dl>
${isAlbum ? '' : listenBlock(d.listen, work.audio)}
</aside>
</div>
${tracks}
${versions}
${credits ? `<section class="tt-d-section"><h2>${esc(d.credits)}</h2><div class="tt-d-card"><pre class="tt-d-credits">${esc(String(credits).trim())}</pre></div></section>` : ''}
</article>
${pager(lang, list[index - 1], list[index + 1], previewPath, titleOf)}`;
  const schema = { '@type': isAlbum ? 'MusicAlbum' : 'MusicRecording', name: w.title, url: `${baseUrl}${workPath(lang, work)}` };
  return detailPage({
    lang,
    pathFor: (l) => workPath(l, work),
    title: `${w.title} — ${w.artist}`,
    description: description.length > 160 ? `${description.slice(0, 157)}…` : description,
    ogType: isAlbum ? 'music.album' : 'music.song',
    image: assetPath(work.image),
    schema,
    crumbs: [[d.home, `${lang.prefix}/`], [d.works, `${lang.prefix}/works/`], [w.title, previewPath(lang, work)]],
    body,
    preview: true,
  });
}

function newsPage(item, index, lang) {
  const d = detailLabels[lang.key];
  const n = localized(item, lang.key);
  const titleOf = (news) => localized(news, lang.key).title;
  const summary = String(n.summary || '').trim() || String(n.body || '').trim().split('\n')[0];
  const body = `<article class="tt-d-article">
<p class="tt-d-kicker">${esc(n.tag || n.category || '')} · ${esc(item.date)}</p>
<h1>${esc(n.title)}</h1>
</article>
<div class="tt-d-hero is-wide"><figure class="tt-d-cover"><img src="${esc(assetPath(item.image))}" alt="${esc(n.title)}" width="1600" height="900"></figure></div>
<article class="tt-d-article tt-d-section">
${paragraphs(n.body || n.summary)}
<div class="tt-d-actions"><a class="tt-d-button is-ghost" href="${lang.prefix}/news/">${esc(d.allNews)}</a></div>
</article>
${pager(lang, site.news[index - 1], site.news[index + 1], newsPath, titleOf)}`;
  const schema = {
    '@type': 'NewsArticle',
    '@id': `${baseUrl}${newsPath(lang, item)}#article`,
    headline: n.title,
    url: `${baseUrl}${newsPath(lang, item)}`,
    description: summary,
    image: `${baseUrl}${assetPath(item.image)}`,
    datePublished: isoDate(item.date),
    inLanguage: lang.html,
    author: { '@type': 'Organization', '@id': `${baseUrl}/#organization`, name: seo.siteName, url: `${baseUrl}/` },
    publisher: { '@type': 'Organization', '@id': `${baseUrl}/#organization`, name: seo.siteName, logo: { '@type': 'ImageObject', url: `${baseUrl}/assets/icons/icon-512.png` } },
    mainEntityOfPage: `${baseUrl}${newsPath(lang, item)}`,
  };
  return detailPage({
    lang,
    pathFor: (l) => newsPath(l, item),
    title: n.title,
    description: summary.length > 160 ? `${summary.slice(0, 157)}…` : summary,
    ogType: 'article',
    image: assetPath(item.image),
    schema,
    crumbs: [[d.home, `${lang.prefix}/`], [d.news, `${lang.prefix}/news/`], [n.title, newsPath(lang, item)]],
    body,
  });
}

const detailPages = [
  ...worksByDate.flatMap((work, i) => languages.map((lang) => [`${workPath(lang, work).slice(1)}index.html`, workPage(work, i, lang)])),
  ...site.news.flatMap((item, i) => languages.map((lang) => [`${newsPath(lang, item).slice(1)}index.html`, newsPage(item, i, lang)])),
];

function sitemap() {
  const entry = (pathFor) => languages.map((lang) => [
    '  <url>',
    `    <loc>${baseUrl}${pathFor(lang)}</loc>`,
    ...languages.map((l) => `    <xhtml:link rel="alternate" hreflang="${l.html}" href="${baseUrl}${pathFor(l)}"/>`),
    `    <xhtml:link rel="alternate" hreflang="x-default" href="${baseUrl}${pathFor(languages[0])}"/>`,
    '  </url>',
  ].join('\n'));
  const urls = [
    ...seo.pages.flatMap((page) => entry((lang) => `${lang.prefix}${page.path}`)),
    ...worksByDate.flatMap((work) => entry((lang) => workPath(lang, work))),
    ...site.news.flatMap((item) => entry((lang) => newsPath(lang, item))),
  ];
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">
${urls.join('\n')}
</urlset>
`;
}

// ---- Preview of work in progress (taletone.net/preview/, not indexed) ----
// Built from preview-src/ only, into preview/ only: its own app, content, Works script/style/data,
// so a redesign can change text and layout without touching the live site.
const [pTemplate, pComponent, pSiteText, pWorksText, pWorksJs, pWorksCss] = await Promise.all([
  read('preview-src/app/template.html'), read('preview-src/app/component.js'),
  read('preview-src/data/site-content.json'), read('preview-src/data/works-data.json'),
  read('preview-src/js/works.js'), read('preview-src/css/works.css'),
]);
const previewDetailCss = await read('preview-src/css/detail.css');
const previewWorksByDate = [...JSON.parse(pWorksText).works].sort((a, b) => String(b.date).localeCompare(String(a.date)));
const previewTemplate = pTemplate
  .replace(/assets\/css\/works\.css\?v=[\w-]+/, `preview/assets/css/works.css?v=${version(pWorksCss)}`)
  .replace(/assets\/js\/works\.js\?v=[\w-]+/, `preview/assets/js/works.js?v=${version(pWorksJs + pWorksText)}`);
const previewApp = makeAppBundle(previewTemplate, pComponent);
const previewSiteScript = dataScript(JSON.parse(pSiteText), 'TALETONE_CONTENT');
const previewOutputs = [
  ['preview/index.html', renderPage(seo.pages.find((p) => p.key === 'home'), languages[0], {
    APP_VERSION: version(previewApp),
    SITE_VERSION: version(previewSiteScript),
    NANUM_FONT_URL: nanumUrl(await nanumCharacters(root, PREVIEW_SOURCES)),
  }).replace('<html lang="ko">', '<html lang="ko" data-intro-v2>')
    .replace('<meta name="robots" content="index, follow">', '<meta name="robots" content="noindex, nofollow">')
    .replaceAll('"assets/app/app.js?v=', '"preview/assets/app/app.js?v=')
    .replace('"assets/data/site-content.js?v=', '"preview/assets/data/site-content.js?v=')],
  ['preview/assets/app/app.js', previewApp],
  ['preview/assets/data/site-content.js', previewSiteScript],
  ['preview/assets/data/works-data.json', pWorksText],
  ['preview/assets/js/works.js', pWorksJs],
  ['preview/assets/css/works.css', pWorksCss],
  ['preview/assets/css/detail.css', previewDetailCss],
  ...previewWorksByDate.flatMap((work, i) => languages.map((lang) => [`preview${workPath(lang, work)}index.html`, workPageV2(work, i, lang, previewWorksByDate)])),
];

const outputs = [
  ...seo.pages.flatMap((page) => languages.map((lang) => [fileFor(lang, page.path), renderPage(page, lang)])),
  ...detailPages,
  ['assets/app/app.js', appBundle],
  ...previewOutputs,
  ['assets/data/site-content.js', siteScript],
  ['assets/data/seo-content.js', seoScript],
  ['sitemap.xml', sitemap()],
];

const stale = [];
for (const [relative, content] of outputs) {
  const file = path.join(root, relative);
  let current = null;
  try { current = await readFile(file, 'utf8'); } catch {}
  if (current === content) continue;
  stale.push(relative);
  if (!check) {
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, content);
  }
}

if (check && stale.length) {
  console.error(`Generated files are out of date: ${stale.join(', ')}`);
  console.error('Run `node scripts/build.mjs` and commit the result.');
  process.exit(1);
}
console.log(check
  ? `Generated files are up to date (${outputs.length} files).`
  : stale.length ? `Rebuilt ${stale.length} file(s): ${stale.join(', ')}` : 'All generated files already up to date.');
